 void LayoutKeepaway(){if(!(menus.match is LWS.TruckKeepaway.KeepawayMatch)||root==null)return;root.anchorMin=root.anchorMax=root.pivot=new Vector2(.5f,0);root.anchoredPosition=new Vector2(0,18);root.sizeDelta=new Vector2(menus.match.ScoreCardCount*385-10,76);for(int i=0;i<cards.Length;i++){var card=cards[i];var rect=card.root.GetComponent<RectTransform>();rect.anchoredPosition=new Vector2(i*385,0);rect.sizeDelta=new Vector2(375,72);card.name.rectTransform.anchoredPosition=new Vector2(52,-4);card.name.rectTransform.sizeDelta=new Vector2(240,25);card.name.fontSizeMax=22;card.detail.rectTransform.anchoredPosition=new Vector2(52,-33);card.detail.rectTransform.sizeDelta=new Vector2(292,24);card.detail.fontSizeMax=19;card.value.rectTransform.anchoredPosition=new Vector2(300,-2);card.value.rectTransform.sizeDelta=new Vector2(67,46);card.portrait.rectTransform.anchoredPosition=new Vector2(10,-8);card.portrait.rectTransform.sizeDelta=new Vector2(35,35);card.progress.rectTransform.anchoredPosition=new Vector2(52,-67);card.glyph.rectTransform.anchoredPosition=new Vector2(10,-48);card.padlock.GetComponent<RectTransform>().anchoredPosition=new Vector2(349,-48);var backing=card.root.transform.Find("Input glyph backing");if(backing!=null)backing.gameObject.SetActive(false);}}

 void LayoutTerrier(){if(!(menus.match is LWS.TruckTerrierRacing.TerrierMatch)||root==null)return;root.anchorMin=root.anchorMax=root.pivot=new Vector2(.5f,1);root.anchoredPosition=new Vector2(0,-72);root.sizeDelta=new Vector2(1860,126);for(int i=0;i<cards.Length;i++){var card=cards[i];var rect=(RectTransform)card.root.transform;rect.anchoredPosition=new Vector2(i%6*310,-i/6*65);rect.sizeDelta=new Vector2(304,60);card.name.rectTransform.anchoredPosition=new Vector2(55,-3);card.name.rectTransform.sizeDelta=new Vector2(185,27);card.detail.rectTransform.anchoredPosition=new Vector2(55,-30);card.detail.rectTransform.sizeDelta=new Vector2(185,25);card.value.rectTransform.anchoredPosition=new Vector2(244,-6);card.value.rectTransform.sizeDelta=new Vector2(52,46);card.portrait.rectTransform.sizeDelta=new Vector2(37,37);}}
 // Eight-card mode uses one bottom row; other sports retain their existing grids.
 int compactCount=-1,compactColumns=-1;
 void LayoutCompactGrid(){
  int requested=menus.match.CompactScoreColumns;
  if(requested<1||root==null)return;
  int count=menus.match.ScoreCardCount;
  int columns=Mathf.Clamp(requested,1,8);
  bool singleRow=requested==8;
  if(singleRow)columns=Mathf.Clamp(count,1,8);
  if(compactCount==count&&compactColumns==columns)return;
  compactCount=count;compactColumns=columns;
  int rows=Mathf.CeilToInt((float)count/columns);
  float width=1860f/columns;
  root.anchorMin=root.anchorMax=root.pivot=new Vector2(.5f,0);
  // Status plate occupies y=12..64. Card bottoms sit at y=72 (eight-pixel gap).
  root.anchoredPosition=new Vector2(0,singleRow?68:88);
  root.sizeDelta=new Vector2(1860,rows*(singleRow?68:65));
  for(int i=0;i<cards.Length;i++){
   var card=cards[i];var rect=(RectTransform)card.root.transform;
   rect.anchoredPosition=new Vector2(i%columns*width,singleRow?0:rows*65-i/columns*65);
   rect.sizeDelta=new Vector2(width-6,singleRow?64:60);
   card.name.rectTransform.anchoredPosition=new Vector2(singleRow?45:55,singleRow?-4:-3);
   card.name.rectTransform.sizeDelta=new Vector2(singleRow?width-79:width-170,27);
   card.detail.rectTransform.anchoredPosition=new Vector2(singleRow?12:55,-30);
   card.detail.rectTransform.sizeDelta=new Vector2(singleRow?width-104:width-65,25);
   card.value.rectTransform.anchoredPosition=new Vector2(width-(singleRow?84:110),singleRow?-28:-4);
   card.value.rectTransform.sizeDelta=new Vector2(singleRow?72:98,singleRow?30:42);
   card.portrait.rectTransform.sizeDelta=new Vector2(singleRow?30:37,singleRow?30:37);
   card.padlock.GetComponent<RectTransform>().anchoredPosition=new Vector2(width-31,-38);
   card.progress.rectTransform.anchoredPosition=new Vector2(12,singleRow?-61:-57);
   if(singleRow){
    card.name.fontSizeMax=22;card.name.fontSizeMin=16;
    card.detail.fontSizeMax=17;card.detail.fontSizeMin=14;
    card.value.fontSizeMax=26;card.value.fontSizeMin=22;
    card.portrait.rectTransform.anchoredPosition=new Vector2(9,-6);
    card.glyph.rectTransform.anchoredPosition=new Vector2(width-29,-8);
    var backing=card.root.transform.Find("Input glyph backing");if(backing!=null)backing.gameObject.SetActive(false);
   }
  }
 }
 SportsBroadcastTheme theme;Card[] cards;string prior;float next;RectTransform root;bool mapped;
 TMP_Text Text(Transform parent,string name,Vector2 position,Vector2 size,int font,bool bold){var g=new GameObject(name,typeof(RectTransform));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=position;r.sizeDelta=size;var text=g.AddComponent<TextMeshProUGUI>();text.font=bold?headingFont:bodyFont;text.fontSize=font;text.enableAutoSizing=true;text.fontSizeMin=font-2;text.fontSizeMax=font;text.color=SportsBroadcastCanvas.Cream;text.raycastTarget=false;text.alignment=TextAlignmentOptions.MidlineLeft;text.overflowMode=TextOverflowModes.Ellipsis;return text;}
 Image Block(Transform parent,string name,Vector2 position,Vector2 size,Color color){var g=new GameObject(name,typeof(RectTransform),typeof(Image));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=position;r.sizeDelta=size;var image=g.GetComponent<Image>();image.color=color;image.raycastTarget=false;return image;}
 void Build(){theme=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme");menus.standings.outlineColor=SportsBroadcastCanvas.Ink;menus.standings.outlineWidth=.24f;var holder=new GameObject("Broadcast participant cards",typeof(RectTransform));root=holder.GetComponent<RectTransform>();root.SetParent(menus.hud.transform,false);root.anchorMin=root.anchorMax=root.pivot=new Vector2(0,1);root.anchoredPosition=new Vector2(16,-76);root.sizeDelta=new Vector2(345,820);cards=new Card[menus.match.MaximumPlayers];for(int i=0;i<cards.Length;i++){var g=new GameObject("Participant card "+i,typeof(RectTransform),typeof(Image),typeof(SportsBroadcastPlate));g.transform.SetParent(root,false);var rect=g.GetComponent<RectTransform>();rect.anchorMin=rect.anchorMax=rect.pivot=new Vector2(0,1);rect.anchoredPosition=new Vector2(0,-i*65);rect.sizeDelta=new Vector2(345,60);g.GetComponent<Image>().color=SportsBroadcastCanvas.Ink;var stripe=new GameObject("Participant color",typeof(RectTransform),typeof(Image));stripe.transform.SetParent(g.transform,false);var sr=stripe.GetComponent<RectTransform>();sr.anchorMin=new Vector2(0,0);sr.anchorMax=new Vector2(0,1);sr.pivot=new Vector2(0,.5f);sr.offsetMin=new Vector2(0,6);sr.offsetMax=new Vector2(4,-6);cards[i]=new Card{root=g,stripe=stripe.GetComponent<Image>(),name=Text(g.transform,"Name",new Vector2(64,-3),new Vector2(205,27),23,true),value=Text(g.transform,"Score badge",new Vector2(277,-6),new Vector2(60,46),30,true),detail=Text(g.transform,"Status",new Vector2(64,-30),new Vector2(205,25),20,false)};cards[i].name.fontSizeMin=17;cards[i].portrait=Block(g.transform,"Actual truck portrait",new Vector2(11,-7),new Vector2(45,45),Color.white);cards[i].portrait.sprite=Resources.Load<Sprite>("Broadcast truck portrait");cards[i].portrait.preserveAspect=true;Block(g.transform,"Input glyph backing",new Vector2(38,-37),new Vector2(22,22),SportsBroadcastCanvas.Ink);cards[i].glyph=Block(g.transform,"Assigned input glyph",new Vector2(39,-38),new Vector2(20,20),SportsBroadcastCanvas.Cream);cards[i].glyph.preserveAspect=true;cards[i].value.alignment=TextAlignmentOptions.Center;cards[i].progress=Block(g.transform,"Capture progress",new Vector2(13,-57),new Vector2(260,3),SportsBroadcastCanvas.Cream);var lockRoot=new GameObject("Capture lock",typeof(RectTransform));lockRoot.transform.SetParent(g.transform,false);var lr=lockRoot.GetComponent<RectTransform>();lr.anchorMin=lr.anchorMax=lr.pivot=new Vector2(0,1);lr.anchoredPosition=new Vector2(314,-38);lr.sizeDelta=new Vector2(18,18);Color red=new Color(1,.25f,.2f);Block(lr,"Lock body",new Vector2(1,-7),new Vector2(15,10),red);Block(lr,"Shackle left",new Vector2(4,-1),new Vector2(3,8),red);Block(lr,"Shackle right",new Vector2(11,-1),new Vector2(3,8),red);Block(lr,"Shackle crown",new Vector2(4,0),new Vector2(10,3),red);cards[i].padlock=lockRoot;}}
 void LateUpdate(){if(menus==null||headingFont==null||bodyFont==null)return;if(cards==null){Build();LayoutKeepaway();LayoutTerrier();LayoutCompactGrid();}bool showing=menus.match.BroadcastStandingsVisible&&menus.Screen==SportsEventScreen.Play&&!menus.match.MultiViewHUD;root.gameObject.SetActive(showing&&mapped);if(!showing)return;if(Time.unscaledTime<next)return;next=Time.unscaledTime+.1f;LayoutKeepaway();LayoutCompactGrid();string source=menus.standings.text;bool direct=menus.match.TryReadScoreCard(0,out var firstScore,out var firstDetail);bool found=direct;for(int i=0;i<menus.match.ScoreCardCount;i++)if(source.Contains(menus.match.ScoreCardLabel(i))){found=true;break;}mapped=found;root.gameObject.SetActive(found);menus.standings.gameObject.SetActive(!found);if(!found||!direct&&source==prior)return;prior=source;source=Regex.Replace(source,"<[^>]*>","");var lines=source.Replace("    |    ","\n").Split('\n');for(int i=0;i<cards.Length;i++){var card=cards[i];bool active=i<menus.match.ScoreCardCount;card.root.SetActive(active);if(!active)continue;var player=menus.match.setup.players[menus.match.ScoreCardSource(i)];string label=menus.match.ScoreCardLabel(i);Color identifyingColor=menus.match.ScoreCardColor(i);float progress=menus.match.ParticipantProgress(i);card.progress.gameObject.SetActive(progress>=0);card.progress.rectTransform.sizeDelta=new Vector2((menus.match.CompactScoreColumns==8?((RectTransform)card.root.transform).rect.width-24:260)*Mathf.Clamp01(progress),3);card.progress.color=player.color;card.padlock.SetActive(menus.match.ParticipantLocked(i));card.name.text=label;card.name.color=card.stripe.color=identifyingColor;card.portrait.color=Color.Lerp(identifyingColor,Color.white,.35f);card.glyph.sprite=theme==null?null:player.source==LWS.TruckBowling.BowlingSource.WholeController?theme.controllerGlyph:player.source==LWS.TruckBowling.BowlingSource.LeftStick?theme.leftStickGlyph:player.source==LWS.TruckBowling.BowlingSource.RightStick?theme.rightStickGlyph:null;card.glyph.gameObject.SetActive(card.glyph.sprite!=null);string detail="";foreach(var line in lines){int at=line.IndexOf(label,StringComparison.Ordinal);if(at>=0){detail=line.Substring(at+label.Length).Trim(' ','·','|');break;}}if(menus.match is LWS.TruckTerrierRacing.TerrierMatch terrier){var racer=terrier.racers[i];detail=terrier.wins[i]+" / 5 · "+(racer.Finished?"FINISHED":racer.Alive?"RACING":"OUT");}else if(menus.match is LWS.TruckCurling.CurlingMatch curling){bool delivering=curling.Phase==LWS.TruckCurling.CurlingPhase.Approach||curling.Phase==LWS.TruckCurling.CurlingPhase.Slide;detail=delivering&&curling.Current.truck.slot==menus.match.ScoreCardSource(i)?"DELIVERING":"READY";}var number=Regex.Match(detail,@"^[-+]?\d+(?:\.\d+)?");string score=number.Success?number.Value:"—";bool typed=menus.match.TryReadScoreCard(i,out var typedScore,out var typedDetail);if(typed){score=typedScore;detail=typedDetail;}if(card.priorScore!=null&&card.priorScore!=score){card.value.transform.DOKill();card.value.transform.localScale=Vector3.one;card.value.transform.DOPunchScale(Vector3.one*.18f,.28f,2,.4f).SetUpdate(true).SetLink(card.root);}card.priorScore=score;card.value.text=score;card.detail.text=typed?detail:number.Success?detail.Substring(number.Length).Trim():detail;if(card.detail.text.Length==0)card.detail.text="READY";}}
